1	import type { Face, Tone } from "./state";
2	
3	/**
4	 * A key face as SVG.
5	 *
6	 * SVG, because it needs no rasterizer and no native module in a package
7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
8	 * rejects a raw SVG string despite the documentation. 144 square is the
9	 * @2x size; the software scales it to any key.
10	 *
11	 * The palette is the app's own: celadon for a live key, kiln for a
12	 * refusal, the muted ink for a key with nothing to do. System sans, since
13	 * a font in an SVG would have to travel as base64 on every redraw.
14	 */
15	const TONE: Record<Tone, { ground: string; ink: string; edge: string }> = {
16	  live: { ground: "#1e2f27", ink: "#e7eae6", edge: "#8cc3a6" },
17	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733" },
18	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
19	};
20	
21	const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
22	
23	/**
24	 * Glyph widths in em for the system sans at weight 600 - Segoe UI Semibold
25	 * on Windows, and near enough everywhere else. Counting characters was
26	 * pessimistic: "connected" is nine narrow letters and fits at 26, but a
27	 * count of ten sends it to 22. So the face measures instead, in classes
28	 * coarse enough to read and close enough that the rendered ink stays
29	 * inside the frame.
30	 */
31	const EM: Record<string, number> = {};
32	for (const c of "ijl'.,:;!| ") EM[c] = 0.28;
33	for (const c of "ftrI") EM[c] = 0.36;
34	for (const c of "mw") EM[c] = 0.85;
35	for (const c of "MW") EM[c] = 0.92;
36	EM["…"] = 0.9;
37	
38	function em(ch: string): number {
39	  const known = EM[ch];
40	  if (known !== undefined) return known;
41	  if (/[0-9a-z]/.test(ch)) return 0.55;
42	  if (/[A-Z]/.test(ch)) return 0.68;
43	  return 0.6;
44	}
45	
46	/** How wide a line of text draws, in px, at this font size. */
47	export function measure(text: string, size: number): number {
48	  let w = 0;
49	  for (const ch of text) w += em(ch);
50	  return w * size;
51	}
52	
53	/**
54	 * The frame's usable width. 144 less 8 either side: the stroke is 3px wide
55	 * centered at x=3, so 8 leaves 5px of clear ground inside it. Text is
56	 * centered on 72, so a line no wider than this never reaches x=8 or x=136.
57	 */
58	const LINE = 144 - 2 * 8;
59	const MAX_LINES = 3;
60	
61	/**
62	 * Greedy word wrap by measured width: pack words onto a line up to `width`
63	 * px at `size`, at most `lines` lines. A word too wide for a line of its
64	 * own is broken by characters and carries on below. The last line gets an
65	 * ellipsis if any text was left over.
66	 */
67	export function wrap(text: string, size: number, width = LINE, lines = MAX_LINES): string[] {
68	  const words = text.split(/\s+/).filter(Boolean);
69	  const out: string[] = [];
70	  let i = 0;
71	  while (i < words.length && out.length < lines) {
72	    const word = words[i]!;
73	    if (measure(word, size) > width) {
74	      let cut = "";
75	      for (const ch of word) {
76	        if (measure(cut + ch, size) > width) break;
77	        cut += ch;
78	      }
79	      // One glyph always goes, or a face narrower than its own type would
80	      // loop here forever.
81	      if (cut === "") cut = [...word][0]!;
82	      out.push(cut);
83	      words[i] = word.slice(cut.length);
84	      continue;
85	    }
86	    let line = word;
87	    i++;
88	    while (i < words.length && measure(line + " " + words[i], size) <= width) {
89	      line += " " + words[i];
90	      i++;
91	    }
92	    out.push(line);
93	  }
94	  if (i < words.length && out.length > 0) {
95	    let last = out[out.length - 1]!;
96	    while (last.length > 0 && measure(last + "…", size) > width) last = last.slice(0, -1);
97	    out[out.length - 1] = last + "…";
98	  }
99	  return out;
100	}
101	
102	/**
103	 * The type scale, biggest first. Every step gets the same three lines and
104	 * the same 128px; what changes is how much of a phrase that holds. A title
105	 * takes the first step that keeps every word whole; one too long for the
106	 * last step is wrapped to it anyway and ellipsized rather than drawn over
107	 * the frame.
108	 */
109	const SCALE = [40, 34, 30, 26, 22] as const;
110	
111	/** Whether wrapping at this size keeps every word of the phrase. */
112	function whole(text: string, size: number): boolean {
113	  return wrap(text, size).join(" ") === text.split(/\s+/).filter(Boolean).join(" ");
114	}
115	
116	function typeset(text: string): { lines: string[]; size: number } {
117	  const size = SCALE.find((s) => whole(text, s)) ?? SCALE[SCALE.length - 1]!;
118	  return { lines: wrap(text, size), size };
119	}
120	
121	export function faceImage(face: Face): string {
122	  const t = TONE[face.tone];
123	  const { lines, size } = typeset(face.title);
124	  const top = 72 - ((lines.length - 1) * size * 1.15) / 2 + (face.when ? -8 : 0);
125	  // One positioned <text> per line, baseline given outright: the software
126	  // draws SVG with a renderer that honors x and y on a text element and
127	  // little else - a tspan with its own position, or a dominant-baseline,
128	  // left every title off the key while the small line beneath it showed.
129	  // 0.36em is where the middle of a semibold sans sits above its baseline.
130	  const spans = lines
131	    .map(
132	      (l, i) =>
133	        `<text class="t" x="72" y="${(top + i * size * 1.15 + size * 0.36).toFixed(1)}" text-anchor="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="Segoe UI, Helvetica Neue, Helvetica, Arial, sans-serif">${esc(l)}</text>`,
134	    )
135	    .join("");
136	  const when = face.when
137	    ? `<text x="72" y="128" text-anchor="middle" font-size="12" fill="${t.edge}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(face.when.slice(0, 18))}</text>`
138	    : "";
139	  const svg =
140	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
141	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
142	    // thing even when the drawn lines above cut it short.
143	    `<title>${esc(face.title)}</title>` +
144	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
145	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="3"/>` +
146	    spans +
147	    when +
148	    `</svg>`;
149	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
150	}
