1	/**
2	 * Everything the plugin decides, with nothing from the SDK in it.
3	 *
4	 * A key face is a function of what the plugin knows: whether it is
5	 * signed in, whether its socket is open, which runs are held, which is
6	 * pinned, and what that run last published. `reduce` moves the state on
7	 * one event at a time; the `*Face` functions read it. Keeping them pure
8	 * is what lets the twelve states a key can be in have a test each.
9	 */
10	
11	/**
12	 * What a deck may press, right now, in the pack's own words.
13	 *
14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
15	 * from `apps/web`, so this shape is mirrored rather than shared.
16	 */
17	export interface Offer {
18	  seq: number;
19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
20	  moves: Array<{ id: string; label: string }>;
21	  undo: { what: string } | null;
22	  /** Why a deck cannot press this, in words a key face can carry. */
23	  needsPage: string | null;
24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
25	  /** The setups the run could hand out, empty where the run names no tool or is not live. */
26	  setups: Array<{ id: string; title: string }>;
27	}
28	
29	export type SessionState = "none" | "expired" | "ok";
30	export type SocketState = "closed" | "connecting" | "open";
31	export interface HeldRun {
32	  id: string;
33	  name?: string;
34	  packTitle?: string;
35	}
36	export interface Snapshot {
37	  unit?: number;
38	  words?: { unit: string };
39	  score?: { text: string };
40	  latest?: { text: string } | null;
41	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
42	  standings?: Array<{ name: string; points: number; place: number }>;
43	  counters?: Array<{ id: string; label: string; value: number }>;
44	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
45	  at?: string;
46	  offer?: Offer;
47	}
48	export interface DeckState {
49	  session: SessionState;
50	  /** Whether the streamer has switched the deck on. No socket while false. */
51	  on: boolean;
52	  /** Whether the last time it went off, it was the idle timer rather than a press. */
53	  idleOff: boolean;
54	  socket: SocketState;
55	  runs: HeldRun[];
56	  any: boolean;
57	  pinned: string | null;
58	  attached: string | null;
59	  snapshot: Snapshot | null;
60	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
61	}
62	export type Tone = "live" | "dim" | "refuse";
63	export interface Face {
64	  title: string;
65	  tone: Tone;
66	  when?: string;
67	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
68	  fraction?: number;
69	}
70	export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
71	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
72	export type DeckEvent =
73	  | { t: "session"; state: SessionState }
74	  | { t: "on"; on: boolean; idle?: boolean }
75	  | { t: "socket"; state: SocketState }
76	  | { t: "runs"; runs: HeldRun[]; any: boolean }
77	  | { t: "pin"; id: string | null }
78	  | { t: "snapshot"; snapshot: Snapshot }
79	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
80	  | { t: "tick" };
81	
82	const FLASH_MS = 3000;
83	
84	/** How long a connection that is holding nothing waits before closing itself. */
85	export const IDLE_OFF_MS = 30 * 60_000;
86	
87	export function initial(): DeckState {
88	  return {
89	    session: "none",
90	    on: false,
91	    idleOff: false,
92	    socket: "closed",
93	    runs: [],
94	    any: false,
95	    pinned: null,
96	    attached: null,
97	    snapshot: null,
98	    flash: null,
99	  };
100	}
101	
102	export function attachedRun(state: DeckState): string | null {
103	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
104	  return state.runs.length === 1 ? state.runs[0]!.id : null;
105	}
106	
107	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
108	  switch (event.t) {
109	    case "session":
110	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
111	    case "on":
112	      // Going off is a full stop: no socket, nothing held, nothing to draw
113	      // a number from. The pin is a preference, not a holding, and stays.
114	      return event.on
115	        ? { ...state, on: true, idleOff: false }
116	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
117	    case "socket":
118	      return event.state === "open"
119	        ? { ...state, socket: "open" }
120	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
121	    case "runs": {
122	      const next = { ...state, runs: event.runs, any: event.any };
123	      const attached = attachedRun(next);
124	      // A run that went away takes its numbers with it; a run that is
125	      // still here keeps them until the next snapshot lands.
126	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
127	    }
128	    case "pin": {
129	      const next = { ...state, pinned: event.id };
130	      const attached = attachedRun(next);
131	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
132	    }
133	    case "snapshot":
134	      return { ...state, snapshot: event.snapshot };
135	    case "drove": {
136	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
137	      // A `drove` verdict is the freshest seq source: the next press
138	      // should not carry a seq gone stale while it was in flight.
139	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
140	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
141	    }
142	    case "tick": {
143	      const expired = state.flash !== null && state.flash.until <= now;
144	      // Controller ruling 3: a dial redraws every second while a clock is
145	      // running, so its remaining time keeps moving between snapshots. An
146	      // idle deck has nothing that changes on the tick, so it stays the
147	      // same object and nothing redraws.
148	      const running = state.snapshot?.clocks?.some((c) => c.status === "running") ?? false;
149	      if (!expired && !running) return state;
150	      return expired ? { ...state, flash: null } : { ...state };
151	    }
152	  }
153	}
154	
155	/** What a key says about the run once the deck is signed in and switched on. */
156	function held(state: DeckState): Face | null {
157	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
158	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
159	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
160	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
161	  return null;
162	}
163	
164	/** The state every key shares before any of them has something of its own to say. */
165	function common(state: DeckState): Face | null {
166	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
167	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
168	  // A key that depends on the connection says to make it first: the state
169	  // on top, the thing to do about it beneath.
170	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
171	  return held(state);
172	}
173	
174	/** The run a deck is following, named, or nothing. */
175	function attachedName(state: DeckState): Face | null {
176	  const run = state.runs.find((r) => r.id === state.attached);
177	  if (!run) return null;
178	  return { title: run.name ?? run.packTitle ?? run.id, tone: "live", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
179	}
180	
181	/**
182	 * The Connect key, which reports the connection rather than the run behind it.
183	 *
184	 * It is the one key that has something to say while the deck is off, so it
185	 * skips the "Not connected" every other key stops at and names the state it
186	 * is actually in - down by choice, down by the idle timer, or on its way up.
187	 */
188	export function connectFace(state: DeckState): Face {
189	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
190	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
191	  if (!state.on) return state.idleOff ? { title: "Idle · press to connect", tone: "dim" } : { title: "Offline", tone: "dim" };
192	  if (state.socket === "connecting") return { title: "Connecting", tone: "dim" };
193	  return held(state) ?? attachedName(state) ?? { title: "Connected", tone: "live" };
194	}
195	
196	/**
197	 * When a connection that is holding nothing should close itself.
198	 *
199	 * `since` is when it last had nothing to follow. Null means the clock is not
200	 * running at all - a deck following a live run never times out, however long
201	 * the stream goes, and a deck that is off or still dialing has nothing to
202	 * give up on.
203	 */
204	export function idleDeadline(state: DeckState, since: number): number | null {
205	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
206	  return since + IDLE_OFF_MS;
207	}
208	
209	function flashed(state: DeckState): Face | null {
210	  if (!state.flash || state.flash.ok) return null;
211	  return { title: state.flash.say ?? "No", tone: "refuse" };
212	}
213	
