1	import { describe, expect, it } from "vitest";
2	import {
3	  initial,
4	  reduce,
5	  nextFace,
6	  nextPress,
7	  runFace,
8	  undoFace,
9	  metricFace,
10	  connectFace,
11	  attachedRun,
12	  idleDeadline,
13	  setupFace,
14	  rollFace,
15	  IDLE_OFF_MS,
16	  type DeckState,
17	  type Offer,
18	} from "./state";
19	
20	const held = (id: string, name = "Thursday") => ({ id, name, packTitle: "The Long Kiln" });
21	const offer: Offer = {
22	  seq: 42,
23	  primary: { id: "roll", label: "Roll the Weather", kind: "rollTable" },
24	  moves: [],
25	  undo: { what: "A dry wind." },
26	  needsPage: null,
27	  presets: [],
28	  setups: [],
29	};
30	const T = 1_000_000;
31	
32	// Signed in and switched on: the two things that had to be true before a
33	// key could say anything about a run, now that the socket is a state the
34	// streamer enters rather than a consequence of being configured.
35	const live = (): DeckState => reduce(reduce(initial(), { t: "session", state: "ok" }, T), { t: "on", on: true }, T);
36	const open = (runs = [held("s1")]): DeckState => {
37	  const s = reduce(live(), { t: "socket", state: "open" }, T);
38	  return reduce(s, { t: "runs", runs, any: true }, T);
39	};
40	
41	describe("what the keys say", () => {
42	  it("asks for a sign-in before anything else", () => {
43	    expect(nextFace(initial(), {})).toEqual({ title: "Sign in", tone: "dim" });
44	  });
45	  it("is offline with a session and no socket", () => {
46	    const s = live();
47	    expect(nextFace(s, {})).toEqual({ title: "Offline", tone: "dim" });
48	  });
49	  it("tells nothing synced from nothing open", () => {
50	    let s = live();
51	    s = reduce(s, { t: "socket", state: "open" }, T);
52	    expect(nextFace(reduce(s, { t: "runs", runs: [], any: false }, T), {})).toEqual({ title: "Not synced", tone: "dim" });
53	    expect(nextFace(reduce(s, { t: "runs", runs: [], any: true }, T), {})).toEqual({ title: "No run open", tone: "dim" });
54	  });
55	  it("attaches to the only held run without being asked", () => {
56	    let s = live();
57	    s = reduce(s, { t: "socket", state: "open" }, T);
58	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
59	    expect(attachedRun(s)).toBe("s1");
60	    expect(runFace(s)).toEqual({ title: "Thursday", tone: "live", when: "The Long Kiln" });
61	  });
62	  it("asks to pick between two, and a pin decides", () => {
63	    let s = live();
64	    s = reduce(s, { t: "socket", state: "open" }, T);
65	    s = reduce(s, { t: "runs", runs: [held("s1"), held("s2", "Friday")], any: true }, T);
66	    expect(nextFace(s, {})).toEqual({ title: "Pick a run", tone: "dim" });
67	    expect(attachedRun(reduce(s, { t: "pin", id: "s2" }, T))).toBe("s2");
68	  });
69	  it("a pinned run that ended says so rather than drifting", () => {
70	    let s = live();
71	    s = reduce(s, { t: "socket", state: "open" }, T);
72	    s = reduce(s, { t: "pin", id: "s1" }, T);
73	    s = reduce(s, { t: "runs", runs: [held("s2", "Friday")], any: true }, T);
74	    expect(nextFace(s, {})).toEqual({ title: "That run has ended", tone: "dim" });
75	  });
76	  it("draws the offer's primary, and the reason when there is none", () => {
77	    let s = live();
78	    s = reduce(s, { t: "socket", state: "open" }, T);
79	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
80	    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
81	    expect(nextFace(s, {})).toEqual({ title: "Roll the Weather", tone: "live" });
82	    expect(undoFace(s)).toEqual({ title: "Undo", tone: "live" });
83	    const blocked = reduce(
84	      s,
85	      { t: "snapshot", snapshot: { offer: { ...offer, primary: null, needsPage: "Name the bowl on the page" } } },
86	      T,
87	    );
88	    expect(nextFace(blocked, {})).toEqual({ title: "Name the bowl on the page", tone: "refuse" });
89	  });
90	  it("says Undo either way, and dims it when there is nothing to take back", () => {
91	    let s = open();
92	    s = reduce(s, { t: "snapshot", snapshot: { offer: { ...offer, undo: null } } }, T);
93	    expect(undoFace(s)).toEqual({ title: "Undo", tone: "dim" });
94	  });
95	  it("flashes a refusal for three seconds, then goes back", () => {
96	    let s = live();
97	    s = reduce(s, { t: "socket", state: "open" }, T);
98	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
99	    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
100	    s = reduce(s, { t: "drove", ref: "r1", ok: false, say: "That moved on." }, T);
101	    expect(nextFace(s, {})).toEqual({ title: "That moved on.", tone: "refuse" });
102	    expect(nextFace(reduce(s, { t: "tick" }, T + 3001), {})).toEqual({ title: "Roll the Weather", tone: "live" });
103	  });
104	  it("ticks a running clock from the snapshot's own time", () => {
105	    let s = live();
106	    s = reduce(s, { t: "socket", state: "open" }, T);
107	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
108	    const at = new Date(T).toISOString();
109	    s = reduce(
110	      s,
111	      {
112	        t: "snapshot",
113	        snapshot: { at, clocks: [{ id: "u4", label: "Day 4", kind: "timer", seconds: 600, status: "running", elapsedMs: 10_000 }] },
114	      },
115	      T,
116	    );
117	    // Ruling 4 amends this case: a running timer clock's face also carries
118	    // a fraction (elapsed / total) for a dial's indicator — 15s of 600s.
119	    expect(metricFace(s, "clock", T + 5_000)).toEqual({ title: "9:45", tone: "live", when: "Day 4", fraction: 0.025 });
120	  });
121	
122	  // Controller ruling 1: a `drove` that carries `seq` is the freshest seq
123	  // source, so the next press is not stale; one without `seq` leaves the
124	  // held offer's seq alone.
125	  it("keeps a driven verdict's seq, but only when it carries one", () => {
126	    let s = live();
127	    s = reduce(s, { t: "socket", state: "open" }, T);
128	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
129	    s = reduce(s, { t: "snapshot", snapshot: { offer } }, T);
130	    const driven = reduce(s, { t: "drove", ref: "r1", ok: true, seq: 43 }, T);
131	    expect(driven.snapshot?.offer?.seq).toBe(43);
