133	    expect(untouched.snapshot?.offer?.seq).toBe(42);
134	  });
135	
136	  // Controller ruling 4: a running timer clock carries a fraction so a
137	  // dial's indicator can draw it.
138	  it("gives a running timer's face a fraction for the dial", () => {
139	    let s = live();
140	    s = reduce(s, { t: "socket", state: "open" }, T);
141	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
142	    const at = new Date(T).toISOString();
143	    s = reduce(
144	      s,
145	      {
146	        t: "snapshot",
147	        snapshot: { at, clocks: [{ id: "u4", label: "Day 4", kind: "timer", seconds: 600, status: "running", elapsedMs: 0 }] },
148	      },
149	      T,
150	    );
151	    expect(metricFace(s, "clock", T + 15_000).fraction).toBe(0.025);
152	  });
153	
154	  // Controller ruling 3: the tick reaches a dial holding a running clock,
155	  // but does nothing to a deck with nothing counting down.
156	  it("re-ticks a running clock but not an idle deck", () => {
157	    let s = live();
158	    s = reduce(s, { t: "socket", state: "open" }, T);
159	    s = reduce(s, { t: "runs", runs: [held("s1")], any: true }, T);
160	    const at = new Date(T).toISOString();
161	    const running = reduce(
162	      s,
163	      {
164	        t: "snapshot",
165	        snapshot: { at, clocks: [{ id: "u4", label: "Day 4", kind: "timer", seconds: 600, status: "running", elapsedMs: 0 }] },
166	      },
167	      T,
168	    );
169	    expect(reduce(running, { t: "tick" }, T + 1000)).not.toBe(running);
170	
171	    const idle = reduce(
172	      s,
173	      {
174	        t: "snapshot",
175	        snapshot: { at, clocks: [{ id: "u4", label: "Day 4", kind: "timer", seconds: 600, status: "paused", elapsedMs: 0 }] },
176	      },
177	      T,
178	    );
179	    expect(reduce(idle, { t: "tick" }, T + 1000)).toBe(idle);
180	    expect(reduce(s, { t: "tick" }, T + 1000)).toBe(s);
181	  });
182	});
