// Temporary calibration script for task 21. Delete before committing.
import { Resvg } from "@resvg/resvg-js";
import { faceImage } from "./face.ts";

const cases = [
  { title: "2", when: "Deaths" },
  { title: "Not connected", when: "press Connect" },
  { title: "Leveling", when: "Apply setup" },
  { title: "Weather", when: "Scenes before a warp" },
];

for (const c of cases) {
  const uri = faceImage({ title: c.title, tone: "live", when: c.when });
  const svg = Buffer.from(uri.split(",")[1], "base64").toString("utf8");
  const png = new Resvg(svg, { fitTo: { mode: "width", value: 144 }, font: { loadSystemFonts: true } }).render();
  const { width, height, pixels } = png;
  // Find the when line's ink bounding box: scan rows 100-136 (below the
  // title block) for non-background pixels, using alpha as the signal.
  let minX = width;
  let maxX = -1;
